select null, t.id, 'builtin', 'Amyloid stained with Congo red and viewed under polarized light shows:', '["Red-orange fluorescence","Blue-black granules","Apple-green birefringence","Magenta staining"]'::jsonb, 2, 'Apple-green birefringence of Congo red–stained amyloid under a polarizing microscope remains the gold standard; it shows properly only when the two filters are accurately crossed. Reference: Song et al., Congo red staining with fluorescence microscopy in primary cutaneous amyloidosis, J Dermatol 2025 (pmc.ncbi.nlm.nih.gov/articles/PMC11807360).', 1, 'verified'
