select null, t.id, 'builtin', 'Oil Red O staining for fat is done on fresh (frozen) tissue because:', '["The dye only works below 0 °C","Paraffin destroys the dye","Frozen tissue absorbs more dye","Alcohol used in fixation and processing removes most lipids"]'::jsonb, 3, 'Oil Red O for fat is performed on frozen sections, because the alcohol used in fixation and paraffin processing removes most lipids. Reference: Krishna, Role of special stains in diagnostic liver pathology, Clin Liver Dis 2013 (pmc.ncbi.nlm.nih.gov/articles/PMC6448668).', 2, 'verified'
