select null, t.id, 'builtin', 'The classic Papanicolaou stain is a:', '["5-dye method","2-dye method","Single silver stain","3-dye method"]'::jsonb, 0, 'The Pap stain is a 5-dye method: hematoxylin for nuclei plus Orange G and EA (light green, Bismarck brown and eosin) for cytoplasm. Reference: Chantziantoniou et al., Inception and Development of the Papanicolaou Stain Method, Acta Cytol 2017 (doi.org/10.1159/000457827).', 2, 'verified'
