insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'For a Pap test, cells are collected from:', '["The posterior vaginal wall only","The transformation zone, where squamous cells meet glandular endocervical cells","The endometrial cavity","The surface of the ovary"]'::jsonb, 1, 'The adequacy of a Pap smear depends on sampling the transformation zone, where the squamous and glandular (columnar) cells meet at the squamocolumnar junction. Reference: Cervical Cancer Prevention - Cervical Screening: Science in Evolution (pmc.ncbi.nlm.nih.gov/articles/PMC2762353).', 1, 'verified'
