insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'In the Bethesda system, ASC-US stands for:', '["Atypical squamous cells, suspicious for cancer","Abnormal squamous carcinoma, unspecified site","Atypical squamous cells, cannot exclude HSIL","Atypical squamous cells of undetermined significance"]'::jsonb, 3, 'ASC-US means atypical squamous cells of undetermined significance. ASC-H is a separate category: atypical squamous cells where HSIL cannot be excluded. References: Alrajjal et al., Squamous intraepithelial lesions of the uterine cervix and the Bethesda System, CytoJournal 2021 (pmc.ncbi.nlm.nih.gov/articles/PMC8326095); National Cancer Institute, HPV and Pap Test Results (cancer.gov/types/cervical/understanding-abnormal-hpv-and-pap-test-results).', 1, 'verified'
