insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'A patient agrees to a test only because the staff pressured them. Which part of informed consent is missing?', '["Disclosure","Voluntariness","Capacity","Documentation"]'::jsonb, 1, 'Consent must be voluntary; coercion and manipulation are unethical and illegal ways of obtaining consent. Capacity and disclosure are the other two elements. Reference: Core concepts of consent in medical practice (pmc.ncbi.nlm.nih.gov/articles/PMC10335635).', 1, 'verified'
