insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'A caller says they are the patient''s officemate and asks for the patient''s HIV test result. The medical technologist should:', '["Give it, since the caller knows the patient","Give it only if the result is negative","Give it to the caller''s supervisor instead","Decline, because results are confidential and need the patient''s consent"]'::jsonb, 3, 'Protecting confidential information is part of respecting the patient''s autonomy. Under the Data Privacy Act, health information is sensitive personal information, which generally needs the patient''s consent before it is shared. References: The 4 basic ethical principles (pmc.ncbi.nlm.nih.gov/articles/PMC4863255); RA 10173, Sections 3 and 13 (lawphil.net/statutes/repacts/ra2012/ra_10173_2012.html).', 1, 'verified'
