insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'To pass the medical technology board exam under RA 5527, a candidate needs:', '["A general average of 70%, with no rating below 40%","A general average of at least 75%, with no rating below 50% in any major subject","A general average of 75%, with no rating below 60%","At least 80% in every subject"]'::jsonb, 1, 'Section 19: a candidate must get a general average of at least 75% in the written test, with no rating below 50% in any of the major subjects. Reference: RA 5527 full text (lawphil.net/statutes/repacts/ra1969/ra_5527_1969.html).', 1, 'verified'
from topics t join subjects s on s.id = t.subject_id
where s.code = 'HTMLE' and t.name = 'MT Laws'
  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('To pass the medical technology board exam under RA 5527, a candidate needs:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
